<?php
 namespace Pterodactyl\Services\Dezerx\Rust; use Throwable; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\Log; class RustSteamService { public const DEFAULT_AVATAR = 'https://avatars.steamstatic.com/fef49e7fa7e1997310d705b2a6158ff8dc1cdfeb_full.jpg'; public static function getPlayerSummary(string $steamId): array { $steamId = trim($steamId); if (!preg_match('/^[0-9]{15,20}$/', $steamId)) { return [ 'steamId' => $steamId, 'name' => 'Rust Player', 'avatar' => self::DEFAULT_AVATAR, 'profileUrl' => "https://steamcommunity.com/profiles/{$steamId}", ]; } return Cache::remember("dezerx:rust:steam:{$steamId}", 86400, function () use ($steamId) { try { $url = "https://steamcommunity.com/profiles/{$steamId}/?xml=1"; $response = Http::timeout(4)->get($url); if ($response->successful()) { $xmlString = $response->body(); $xml = @simplexml_load_string($xmlString); if ($xml !== false) { $name = (string) ($xml->steamID ?? ''); $avatarFull = (string) ($xml->avatarFull ?? ''); $avatarMedium = (string) ($xml->avatarMedium ?? ''); $avatar = !empty($avatarFull) ? $avatarFull : (!empty($avatarMedium) ? $avatarMedium : self::DEFAULT_AVATAR); return [ 'steamId' => $steamId, 'name' => !empty($name) ? $name : 'Rust Player', 'avatar' => $avatar, 'profileUrl' => "https://steamcommunity.com/profiles/{$steamId}", ]; } } } catch (Throwable $e) { Log::debug('[RustSteamService] Failed to fetch steam summary', ['steamId' => $steamId, 'error' => $e->getMessage()]); } return [ 'steamId' => $steamId, 'name' => 'Rust Player', 'avatar' => self::DEFAULT_AVATAR, 'profileUrl' => "https://steamcommunity.com/profiles/{$steamId}", ]; }); } public static function getAvatar(string $steamId): string { return self::getPlayerSummary($steamId)['avatar']; } } 